#'
#' @export
pysequentialtests <- function(
    data,
    sens1 = 0.95,
    spec1 = 0.7,
    sens2 = 0.8,
    spec2 = 0.98,
    prevalence = 0.1,
    populationSize = 1000,
    showCosts = FALSE,
    cost1 = 0,
    cost2 = 0,
    showPlot = TRUE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pysequentialtests requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- pysequentialtestsOptions$new(
        sens1 = sens1,
        spec1 = spec1,
        sens2 = sens2,
        spec2 = spec2,
        prevalence = prevalence,
        populationSize = populationSize,
        showCosts = showCosts,
        cost1 = cost1,
        cost2 = cost2,
        showPlot = showPlot,
        showConsole = showConsole)

    analysis <- pysequentialtestsClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

